import{_ as e,c as r,o as t,ah as i}from"./chunks/framework.Dnh4IO1K.js";const p=JSON.parse('{"title":"4、【蒙】 坎下艮上","description":"溫公易說 - 4、【蒙】 坎下艮上","frontmatter":{"title":"4、【蒙】 坎下艮上","description":"溫公易說 - 4、【蒙】 坎下艮上"},"headers":[],"relativePath":"classics/wengong/005.md","filePath":"classics/wengong/005.md"}'),n={name:"classics/wengong/005.md"};function l(h,a,o,s,d,c){return t(),r("div",null,[...a[0]||(a[0]=[i('<h1 id="_4、【蒙】-坎下艮上" tabindex="-1">4、【蒙】 坎下艮上 <a class="header-anchor" href="#_4、【蒙】-坎下艮上" aria-label="Permalink to “4、【蒙】 坎下艮上”">​</a></h1><p>需者，何待時而行之謂也；孚者，見信於人之謂也。夫信者，已之所為也；孚者，待人而後成者也。故夫需之道，利安而不利躁；修己以待人者也，非夫信義著明、道徳光大，則不能以亨也。居正待時，然後吉也；用邪求益，宜其兇也。需以涉難，難可濟也；躁以涉川，沉可必也。</p><h3 id="彖曰-蒙山下有險-險而止-蒙亨以亨行時中也。匪我求童蒙-童蒙求我-志應也。初筮告以剛中也。再三瀆瀆則不告-瀆蒙也。蒙以養正-聖功也。" tabindex="-1">彖曰：蒙山下有險，險而止，蒙亨以亨行時中也。匪我求童蒙，童蒙求我，志應也。初筮告以剛中也。再三瀆瀆則不告，瀆蒙也。蒙以養正，聖功也。 <a class="header-anchor" href="#彖曰-蒙山下有險-險而止-蒙亨以亨行時中也。匪我求童蒙-童蒙求我-志應也。初筮告以剛中也。再三瀆瀆則不告-瀆蒙也。蒙以養正-聖功也。" aria-label="Permalink to “彖曰：蒙山下有險，險而止，蒙亨以亨行時中也。匪我求童蒙，童蒙求我，志應也。初筮告以剛中也。再三瀆瀆則不告，瀆蒙也。蒙以養正，聖功也。”">​</a></h3><p>蒙者何？百姓蚩蚩，莫知所之。聖人教之以道，然後曉然識其是非。故夫蒙者，教人之象也。匪我求童蒙，童蒙求我，孔子曰：&quot;不憤不啟，不悱不發。&quot;夫人不求我而強教之，則志不應而言不從矣。故君子之教，道而弗牽，強而弗抑，開而弗達也。初筮告，再三瀆，瀆則不告，孔子曰：&quot;學而不思則罔，又曰舉一隅不以三隅反則不復也。&quot;陸希聲曰：&quot;初筮告，啟其宗也。再三瀆，以塞聰也。瀆則不告，告乃成蒙也。&quot;夫鍜礪者工也，犀利者金也，植藝者圃也，堅實者木也。則工雖巧，不能持土以為兵，圃雖良，不能植谷而生梓也。故才者天也，不教則棄。教者人也，不才則悖。故人者，受才於天而受教於師。師者決其滯，發其蔽，抑其過，引其不及，以養進其天才而已。繫辭曰：&quot;茍非其人，道不虛行。&quot;此之謂也。</p><h3 id="象曰-山下出泉-蒙。君子以果行育德。" tabindex="-1">象曰：山下出泉，蒙。君子以果行育德。 <a class="header-anchor" href="#象曰-山下出泉-蒙。君子以果行育德。" aria-label="Permalink to “象曰：山下出泉，蒙。君子以果行育德。”">​</a></h3><p>果行者，言其動也。育德者，言其靜也。君子動果而靜專，內明而外晦，此之謂蒙以養正也。</p><h3 id="初六-發矇-利用刑人-用說桎梏-以往吝。-象曰-利用刑人-以正法也。" tabindex="-1">初六：發矇，利用刑人，用說桎梏，以往吝。 象曰：利用刑人，以正法也。 <a class="header-anchor" href="#初六-發矇-利用刑人-用說桎梏-以往吝。-象曰-利用刑人-以正法也。" aria-label="Permalink to “初六：發矇，利用刑人，用說桎梏，以往吝。 象曰：利用刑人，以正法也。”">​</a></h3><h3 id="九二-包蒙-吉。納婦-吉。子克家。-象曰-子克家-剛柔接也。" tabindex="-1">九二：包蒙，吉。納婦，吉。子克家。 象曰：子克家，剛柔接也。 <a class="header-anchor" href="#九二-包蒙-吉。納婦-吉。子克家。-象曰-子克家-剛柔接也。" aria-label="Permalink to “九二：包蒙，吉。納婦，吉。子克家。 象曰：子克家，剛柔接也。”">​</a></h3><h3 id="六三-勿用取女-見金夫-不有躬-無攸利。-象曰-勿用取女-行不順也。" tabindex="-1">六三：勿用取女，見金夫，不有躬，無攸利。 象曰：勿用取女，行不順也。 <a class="header-anchor" href="#六三-勿用取女-見金夫-不有躬-無攸利。-象曰-勿用取女-行不順也。" aria-label="Permalink to “六三：勿用取女，見金夫，不有躬，無攸利。 象曰：勿用取女，行不順也。”">​</a></h3><h3 id="六四-困蒙-吝。-象曰-困蒙之吝-獨逺實也。" tabindex="-1">六四：困蒙，吝。 象曰：困蒙之吝，獨逺實也。 <a class="header-anchor" href="#六四-困蒙-吝。-象曰-困蒙之吝-獨逺實也。" aria-label="Permalink to “六四：困蒙，吝。 象曰：困蒙之吝，獨逺實也。”">​</a></h3><p>孔子曰：困而不學，民斯為下矣。聖人於是爻，將以戒夫不學者也。</p><h3 id="六五-童蒙-吉。-象曰-童蒙之吉-順以巽也。" tabindex="-1">六五：童蒙，吉。 象曰：童蒙之吉，順以巽也。 <a class="header-anchor" href="#六五-童蒙-吉。-象曰-童蒙之吉-順以巽也。" aria-label="Permalink to “六五：童蒙，吉。 象曰：童蒙之吉，順以巽也。”">​</a></h3><p>童蒙者何以吉也？得人而信使之也。昔齊桓公衛靈公之行，犬彘之所不為也。然而大則霸諸侯，小則有一國，其故何哉？有管仲仲叔圉祝鮀王孫賈為之輔也。二君者，天下之不肖君也，得賢人而信使之，猶且安其身而收其功，況明哲之君用忠良之臣者乎？</p><h3 id="上九-擊蒙-不利為寇-利禦寇。-象曰-利用禦寇-上下順也。" tabindex="-1">上九：擊蒙，不利為寇，利禦寇。 象曰：利用禦寇，上下順也。 <a class="header-anchor" href="#上九-擊蒙-不利為寇-利禦寇。-象曰-利用禦寇-上下順也。" aria-label="Permalink to “上九：擊蒙，不利為寇，利禦寇。 象曰：利用禦寇，上下順也。”">​</a></h3>',14)])])}const b=e(n,[["render",l]]);export{p as __pageData,b as default};
